import { expect, test } from "bun:test";

import { classifyCommit, summarizeCommits } from "../src/attribution.ts";

const MODEL = { authored_by: "agent-7", hook_created: false, diff_empty: false };
const BOT = { authored_by: "bot-ci", hook_created: false, diff_empty: false };
const HOOK = { authored_by: "agent-9", hook_created: true, diff_empty: false };

test("plain authored diff is model", () => {
  expect(classifyCommit(MODEL)).toBe("model");
});

test("bot author is autocommit", () => {
  expect(classifyCommit(BOT)).toBe("autocommit");
});

test("hook created commit is autocommit", () => {
  expect(classifyCommit(HOOK)).toBe("autocommit");
});

test("non-object is unknown", () => {
  expect(classifyCommit("nope")).toBe("unknown");
});

test("summarize counts by kind", () => {
  expect(summarizeCommits([MODEL, BOT, HOOK])).toEqual({
    model: 1,
    autocommit: 2,
    missed: 0,
    unknown: 0,
  });
});
